input_schema:
z.object({
  paths: z
    .array(z.string())
    .min(1)
    .describe(
      "Array of file paths to read. Each path must be a string pointing to a valid file within allowed directories.",
    ),
})

z.object({
  source: pathArg("The file or directory to move or rename"),
  destination: pathArg(
    "Its new path, including the name; nothing may exist there yet",
  ),
})

z.object({
  path: pathArg(
    "The file to create, or to overwrite if it exists; its parent directory must exist",
  ),
  content: z
    .string()
    .describe("The complete text the file will contain, replacing any it had"),
})

z.object({
  path: pathArg("The file to append to; it is created if it does not exist"),
  content: z
    .string()
    .describe(
      "Text to append, exactly as given. No newline is added: end it with \\n if the next append should start on a new line.",
    ),
})

z.object({
  path: pathArg("The directory to list"),
})

z.object({
  path: pathArg(
    "The directory to create, with any missing parents; an existing directory is left as is",
  ),
})

z.object({
  path: pathArg("The file or directory to describe"),
})

z.object({
  source: z.string().describe("The file to copy"),
  destination: z
    .string()
    .describe("Where to create the copy; nothing may exist there yet"),
})

z.object({
  path: pathArg("The image, audio or other file to read as base64"),
})

output_schema:
jsonSchema2020({
        content: z.array(
          z.union([
            z.object({
              type: z.enum(["image", "audio"]),
              data: z.string(),
              mimeType: z.string(),
            }),
            z.object({
              type: z.literal("resource"),
              resource: z.object({
                uri: z.string(),
                // Optional, matching the SDK's BlobResourceContents shape (the handler always sets it).
                mimeType: z.string().optional(),
                blob: z.string(),
              }),
            }),
          ]),
        ),
      })
